from z3 import *

num_golfers = 21
num_weeks = 5
num_groups = 7
group_size = 3

solver = Solver()

x = [[Int(f"x_{w}_{p}") for p in range(num_golfers)] for w in range(num_weeks)]

for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(x[w][p] >= 0, x[w][p] < num_groups)

for w in range(num_weeks):
    for g in range(num_groups):
        solver.add(PbEq([(x[w][p] == g, 1) for p in range(num_golfers)], group_size))

for p1 in range(num_golfers):
    for p2 in range(p1 + 1, num_golfers):
        solver.add(PbLe([(x[w][p1] == x[w][p2], 1) for w in range(num_weeks)], 1))

# Symmetry breaking
for p in range(num_golfers):
    solver.add(x[0][p] == p // 3)

for w in range(num_weeks):
    solver.add(x[w][0] == 0)

# Week 1: golfers 0, 3, 6 are in group 0
solver.add(x[1][3] == 0)
solver.add(x[1][6] == 0)

# Week 2: golfers 0, 9, 12 are in group 0
solver.add(x[2][9] == 0)
solver.add(x[2][12] == 0)

# Week 3: golfers 0, 15, 18 are in group 0
solver.add(x[3][15] == 0)
solver.add(x[3][18] == 0)

if solver.check() == sat:
    m = solver.model()
    res = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            res.append(m[x[w][p]].as_long())
    print(res)
else:
    print("UNSAT")

sol = [0, 0, 0, 1, 1, 1, 2, 2, 2, 3, 3, 3, 4, 4, 4, 5, 5, 5, 6, 6, 6, 0, 2, 3, 0, 6, 4, 0, 5, 1, 3, 2, 4, 1, 5, 3, 6, 4, 5, 2, 1, 6, 0, 2, 4, 1, 5, 3, 3, 2, 6, 0, 1, 4, 0, 5, 6, 6, 1, 3, 5, 2, 4, 0, 4, 2, 4, 1, 6, 3, 6, 5, 5, 3, 1, 2, 4, 1, 0, 5, 2, 0, 3, 6, 0, 1, 3, 5, 1, 6, 3, 5, 2, 6, 2, 5, 1, 2, 4, 3, 0, 4, 6, 0, 4]

num_golfers = 21
num_weeks = 5
num_groups = 7
group_size = 3

valid = True
for w in range(num_weeks):
    counts = [0] * num_groups
    for p in range(num_golfers):
        counts[sol[w * num_golfers + p]] += 1
    if any(c != group_size for c in counts):
        print(f"Week {w} invalid counts: {counts}")
        valid = False

pairs = set()
for w in range(num_weeks):
    for p1 in range(num_golfers):
        for p2 in range(p1 + 1, num_golfers):
            if sol[w * num_golfers + p1] == sol[w * num_golfers + p2]:
                if (p1, p2) in pairs:
                    print(f"Pair {p1}, {p2} repeated in week {w}")
                    valid = False
                pairs.add((p1, p2))

print("Valid:", valid)
